	private int GetCurrentNodeIndex()
	{
		int num = mapPlayerTracker.CurrentNodeIndex;
		if (num == -1)
		{
			Debug.Log("------ GetCurrentNodeIndex trying to get a -1 index. Fallback to index 0 --------");
			num = 0;
		}
		return num;
	}

	public bool IsPlayerAtTheBeginningOfTheFirstChapterMap()
	{
		if (CurrentAreaIndex == 0 && CurrentAreaLevelIndex == -1)
		{
			return mapPlayerTracker.CurrentNodeIndex == -1;
		}
		return false;
	}

	public AreaEnum GetCurrentAreaEnum()
	{
		if (!gameController.IsDemo && CurrentAreaIndex == 0 && !saveSystem.IsPassedTroughSentinelShopFirstTime())
		{
			return firstTimePlayingAreaEnum;
		}
		return areaOrder[CurrentAreaIndex];
	}

	public void ResetMapToNewArea()
	{
		mapPlayerTracker.CurrentNodeIndex = -1;
		mapPlayerTracker.CurrentAreaLevelIndex = -1;
		mapPlayerTracker.CurrentAreaIndex = Mathf.Min(CurrentAreaIndex + 1, 3);
		saveSystem.SaveMapPlayerTrackerRepeatedEvents();
		mapHistory.SetupNextAreaAndSaveMapHistory();
		PopulateMap();
		if (IsOnAstreasHeart)
		{
			anomalyLevel.UnsubscribeDifficultyLevelEveryXTurnsEffect();
		}
		ReferenceSingleton<AnalyticsManager>.Instance.StarShardsPerAreaAnalytics(endOfBattleStateCalling: false);
	}

	[Button(null)]
	public void PopulateMap()
	{
		Debug.Log("-----PopulateMap-----");
		OnLastNodeExit = null;
		if (IsOnAstreasHeart)
		{
			astreaLevel.InitializeAstreasHeartLevelAreaOrder(areaOrder);
		}
		map.MapLevels.Clear();
		List<string> battlePackageNamesAlreadyPicked = new List<string>();
		RandomUtilities.SetUnityEngineRandomInitStateSeed(ReferenceSingleton<AssetsReference>.Instance.PlayerRunStats.GetSeed() + CurrentAreaIndex);
		bool flag = ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentCharacter.IsStartingStarBlessingAndDiceUnlocked();
		for (int i = 0; i < CurrentArea.AreaLevels.Length - 1; i++)
		{
			if (!gameController.IsDemo)
			{
				if (CurrentAreaIndex == 0 && !flag && i <= 1)
				{
					continue;
				}
			}
			else if (i <= 1 && ((ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentCharacter == playerProgressionData.MoonieCharacter && playerProgressionData.FirstTimePlayingWithMoonieDemo) || (ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentCharacter == playerProgressionData.CellariusCharacter && playerProgressionData.FirstTimePlayingWithCellariusDemo)))
			{
				continue;
			}
			PopulateMapLevel(i, battlePackageNamesAlreadyPicked);
		}
		PopulateBossLevel();
		PopulateBattleIndexes();
		if (mapPlayerTracker.CurrentAreaIndex != 1 && mapPlayerTracker.CurrentAreaIndex != 2)
		{
			return;
		}
		if (mapPlayerTracker.CurrentAreaLevelIndex > map.MapLevels.Count - 1)
		{
			if (saveSystem.IsOnBattle())
			{
				mapPlayerTracker.CurrentAreaLevelIndex = map.MapLevels.Count - 1;
			}
			else
			{
				mapPlayerTracker.CurrentAreaLevelIndex = map.MapLevels.Count - 2;
			}
		}
		if (mapPlayerTracker.CurrentAreaLevelIndex > -1 && mapPlayerTracker.CurrentNodeIndex > map.MapLevels[mapPlayerTracker.CurrentAreaLevelIndex].NodeDatas.Count - 1)
		{
			mapPlayerTracker.CurrentNodeIndex = map.MapLevels[mapPlayerTracker.CurrentAreaLevelIndex].NodeDatas.Count - 1;
		}
	}

	private void PopulateMapLevel(int index, List<string> battlePackageNamesAlreadyPicked)
	{
		MapLevel mapLevel = new MapLevel();
		map.MapLevels.Add(mapLevel);
		AreaLevel areaLevel = CurrentArea.AreaLevels[index];
		if (new List<AreaLevelEnum>
		{
			AreaLevelEnum.FIRST,
			AreaLevelEnum.SECOND,
			AreaLevelEnum.THIRD,
			AreaLevelEnum.SHUFFLE,
			AreaLevelEnum.BOSS
		}.Contains(areaLevel.AreaLevelEnum))
		{
			int num = areaLevel.BattleNormalAmount + areaLevel.BattleHardAmount;
			for (int i = 0; i < num; i++)
			{
				mapLevel.NodeDatas.Add(new NodeData());
			}
			List<NodeData> nodeDatas = mapLevel.NodeDatas.Duplicate();
			PopulateNormalBattle(battlePackageNamesAlreadyPicked, areaLevel, nodeDatas);
			PopulateHardBattle(battlePackageNamesAlreadyPicked, areaLevel, nodeDatas);
			return;
		}
		if (areaLevel.AreaLevelEnum == AreaLevelEnum.FIXEDLOCATION)
		{
			NodeData nodeData = new NodeData();
			nodeData = areaLevel.Locations[0].GetNodeData();
			mapLevel.NodeDatas.Add(nodeData);
			return;
		}
		if (CurrentAreaIndex == 0 && index == 3)
		{
			if (!gameController.IsDemo)
			{
				if (ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentCharacter.CharacterProgression.CharacterXP == 0 && saveSystem.IsPassedTroughSentinelShopFirstTime())
				{
					mapLevel.NodeDatas.Add(starShardLocation.GetNodeData());
					return;
				}
			}
			else if ((ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentCharacter == playerProgressionData.MoonieCharacter && playerProgressionData.FirstTimePlayingWithMoonieDemo) || (ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentCharacter == playerProgressionData.CellariusCharacter && playerProgressionData.FirstTimePlayingWithCellariusDemo))
			{
				mapLevel.NodeDatas.Add(starShardLocation.GetNodeData());
				return;
			}
		}
		List<Location> list = areaLevel.Locations.DuplicateAsList();
		list.Shuffle();
		List<Location> list2 = new List<Location>();
		for (int j = 0; j < list.Count; j++)
		{
			NodeData nodeData2 = new NodeData();
			Location location = list[j];
			if (location is RandomLocation)
			{
				RandomLocation randomLocation = location as RandomLocation;
				location = randomLocation.GetLocation();
				while (list2.Contains(location))
				{
					location = randomLocation.GetLocation();
				}
				list2.Add(location);
			}
			nodeData2 = location.GetNodeData();
			if (nodeData2.NodeEnum == NodeEnum.EVENT && nodeData2.Event.Contains("Ambush"))
			{
				List<BattleCorruptedAnimals> list3 = new List<BattleCorruptedAnimals>();
				if (nodeData2.Event.Contains("Hard"))
				{
					list3.AddRange(CurrentArea.ShuffleHardBattleCorruptedAnimals);
				}
				else if (CurrentArea.ShuffleBattleCorruptedAnimals.Count > 0)
				{
					list3.AddRange(CurrentArea.ShuffleBattleCorruptedAnimals);
				}
				else
				{
					list3 = CurrentArea.GetNormalBattleCorruptedAnimalsFromAreaLevelsButBoss();
				}
				string text = list3.PopRandom().name;
				while (battlePackageNamesAlreadyPicked.Contains(text))
				{
					text = list3.PopRandom().name;
				}
				battlePackageNamesAlreadyPicked.Add(text);
				nodeData2.BattlePackage = text;
			}
			mapLevel.NodeDatas.Add(nodeData2);
		}
	}

	private void PopulateNormalBattle(List<string> battlePackageNamesAlreadyPicked, AreaLevel currentAreaLevel, List<NodeData> nodeDatas)
	{
		List<BattleCorruptedAnimals> list = new List<BattleCorruptedAnimals>();
		list = ((CurrentArea.ShuffleBattleCorruptedAnimals.Count <= 0) ? currentAreaLevel.BattleCorruptedAnimals.Duplicate() : CurrentArea.ShuffleBattleCorruptedAnimals.Duplicate());
		for (int i = 0; i < currentAreaLevel.BattleNormalAmount; i++)
		{
			string text = list.PopRandom().name;
			while (battlePackageNamesAlreadyPicked.Contains(text))
			{
				text = list.PopRandom().name;
			}
			battlePackageNamesAlreadyPicked.Add(text);
			NodeData nodeData = nodeDatas.PopFirst();
			nodeData.Reward = normalBattleReward.name;
			nodeData.NodeEnum = NodeEnum.BATTLENORMAL;
			_ = map.MapLevels;
			nodeData.BattlePackage = text;
		}
	}

	private void PopulateHardBattle(List<string> battlePackageNamesAlreadyPicked, AreaLevel currentAreaLevel, List<NodeData> nodeDatas)
	{
		if (currentAreaLevel.BattleHardAmount <= 0)
		{
			return;
		}
		List<BattleCorruptedAnimals> list = CurrentArea.ShuffleHardBattleCorruptedAnimals.Duplicate();
		for (int i = 0; i < currentAreaLevel.BattleHardAmount; i++)
		{
			string text = list.PopRandom().name;
			while (battlePackageNamesAlreadyPicked.Contains(text))
			{
				text = list.PopRandom().name;
			}
			battlePackageNamesAlreadyPicked.Add(text);
			NodeData nodeData = nodeDatas.PopRandom();
			if (currentAreaLevel.CorruptedOracleBattle)
			{
				nodeData.Reward = corruptedOracleBattleReward.name;
				nodeData.NodeEnum = NodeEnum.BATTLECORRUPTEDORACLE;
			}
			else
			{
				nodeData.Reward = hardBattleReward.name;
				nodeData.NodeEnum = NodeEnum.BATTLEHARD;
			}
			nodeData.BattlePackage = text;
		}
	}

	private void PopulateBossLevel()
	{
		MapLevel mapLevel = new MapLevel();
		map.MapLevels.Add(mapLevel);
		NodeData nodeData = new NodeData();
		nodeData.Reward = bossBattleReward.name;
		nodeData.NodeEnum = NodeEnum.BATTLEBOSS;
		List<BattleCorruptedAnimals> list = CurrentArea.AreaLevels.Last().BattleCorruptedAnimals.Duplicate();
		nodeData.BattlePackage = list.PopRandom().name;
		if (!IsOnAstreasHeart && anomalyLevel.IsDoubleBossDifficultyLevelActive())
		{
			ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.HiddenAnomalyLevelSecondBossPackageName = list.PopRandom().name;
			saveSystem.SaveHiddenAnomalyLevelSecondBossPackageName();
		}
		mapLevel.NodeDatas.Add(nodeData);
	}

	public void PopulateBattleIndexes()
	{
		battleIndexes.Clear();
		for (int i = 0; i < map.MapLevels.Count; i++)
		{
			NodeData nodeData = map.MapLevels[i].NodeDatas[0];
			if (nodeData.BattlePackage != "" && nodeData.NodeEnum != NodeEnum.EVENT)
			{
				battleIndexes.Add(i);
			}
		}
	}

	private int GetBattleAmount()
	{
		int num = 0;
		for (int i = 0; i < map.MapLevels.Count; i++)
		{
			if (map.MapLevels[i].NodeDatas[0].BattlePackage != "")
			{
				num++;
			}
		}
		return num;
	}

	public void NodePressed(int nodeIndex, int areaLevelIndex)
	{
		bool flag = false;
		if (mapPlayerTracker.CurrentAreaLevelIndex != areaLevelIndex)
		{
			flag = true;
			if (OnLastNodeExit != null)
			{
				OnLastNodeExit();
			}
			OnLastNodeExit = null;
		}
		mapPlayerTracker.CurrentNodeIndex = nodeIndex;
		mapPlayerTracker.CurrentAreaLevelIndex = areaLevelIndex;
		SetBattleScene();
		if (currentReward != null && currentReward.DontGoToBattleScene)
		{
			currentReward.ResetRewardsCounter();
			currentReward.GetReward();
			OnGoToMapAlreadyOnMap.Raise();
		}
		else
		{
			saveSystem.SaveOnBattle(value: true);
			if (ReferenceSingleton<InputManager>.Instance.IsJoystickBeingUsed)
			{
				ReferenceSingleton<InputManager>.Instance.SetJoystickInteractionEnabled(value: false);
			}
			ReferenceSingleton<CoroutineHandler>.Instance.Run(ExitMapCoroutine());
		}
		if (flag)
		{
			saveSystem.SaveLastRunTotalTime();
			saveSystem.SaveMapPlayerTracker(saveFeedback: true, saveAndStoreCache: true);
		}
	}

	private IEnumerator ExitMapCoroutine()
	{
		Debug.Log("Exiting from map!");
		InvokeAlternatives.InvokeAfterMultipleFrames(ReferenceSingleton<CoroutineHandler>.Instance, 5, delegate
		{
			OnToggleMap.Raise(item: false);
		});
		CurrentBattleSceneSetup.SetupScene();
		yield return new WaitForSeconds(0.2f);
	}

	public void ResetCurrentRewardCounter()
	{
		if (currentReward != null)
		{
			currentReward.ResetRewardsCounter();
			return;
		}
		Debug.Log($"Trying to reset Current Reward counter and Current Reward is null. Seed {ReferenceSingleton<AssetsReference>.Instance.PlayerRunStats.GetSeed()}, CurrentNodeIndex {CurrentNodeIndex}, CurrentAreaLevelIndex {CurrentAreaLevelIndex}, CurrentAreaIndex {CurrentAreaIndex}, Reward {CurrentNodeData.Reward}");
	}

	public void OnResetToStartRunState()
	{
		map.MapLevels.Clear();
		mapHistory.OnResetToStartRunState();
		mapPlayerTracker.CurrentNodeIndex = -1;
		mapPlayerTracker.CurrentAreaLevelIndex = -1;
		mapPlayerTracker.CurrentAreaIndex = 0;
	}

	public void SetBattleScene()
	{
		if (overrideSetBattleScene)
		{
			return;
		}
		if (CurrentNodeData.Reward != string.Empty)
		{
			currentReward = clearingRewardsList.GetClearingReward(CurrentNodeData.Reward);
		}
		if (new List<NodeEnum>
		{
			NodeEnum.BATTLENORMAL,
			NodeEnum.BATTLEHARD,
			NodeEnum.BATTLEBOSS,
			NodeEnum.BATTLECORRUPTEDORACLE
		}.Contains(CurrentNodeData.NodeEnum))
		{
			currentBattleSceneSetup = battleSetup;
		}
		else if (CurrentNodeData.NodeEnum == NodeEnum.EVENT || CurrentNodeData.NodeEnum == NodeEnum.NOTRANDOMEVENT)
		{
			currentReward = normalBattleReward;
			currentCustomEventSetup = customEventSetupsList.GetCustomEventSetups(CurrentNodeData.Event);
			EventLocation eventLocation = null;
			for (int i = 0; i < CurrentArea.AreaLevels.Length; i++)
			{
				List<Location> list = CurrentArea.AreaLevels[i].Locations.ToList().FindAll((Location location) => location is EventLocation);
				if (list.Count > 0)
				{
					eventLocation = list.First() as EventLocation;
				}
				if (eventLocation != null)
				{
					break;
				}
			}
			if (eventLocation != null)
			{
				if (!currentCustomEventSetup.CheckConditionToBeSelected())
				{
					RandomUtilities.SetUnityEngineRandomInitStateSeed(ReferenceSingleton<AssetsReference>.Instance.PlayerRunStats.GetSeed() + CurrentAreaIndex);
				}
				while (!currentCustomEventSetup.CheckConditionToBeSelected())
				{
					currentCustomEventSetup = eventLocation.GetCustomEventSetup(ignoreAmbush: true);
					CurrentNodeData.Event = currentCustomEventSetup.name;
				}
			}
			currentBattleSceneSetup = eventSetup;
		}
		else if (CurrentNodeData.NodeEnum == NodeEnum.REWARD)
		{
			currentBattleSceneSetup = rewardSetup;
		}
		else if (CurrentNodeData.NodeEnum == NodeEnum.SHOP)
		{
			currentBattleSceneSetup = shopSetup;
		}
	}

	public void SetOverrideSetBattleScene(bool value)
	{
		overrideSetBattleScene = value;
	}

	public void SetClearingReward(ClearingReward clearingReward, bool goToEndOfBattleState = true)
	{
		if (clearingReward != null)
		{
			clearingReward.ResetRewardsCounter();
		}
		currentReward = clearingReward;
		if (goToEndOfBattleState)
		{
			ReferenceSingleton<GameStateManager>.Instance.SetEndOfBattleStateWithQueueLockFalse();
		}
	}

	public void SetBattleSceneSetupToBattle()
	{
		currentBattleSceneSetup = battleSetup;
	}

	public void SetBattleSceneSetupToReward()
	{
		currentBattleSceneSetup = rewardSetup;
	}

	public int GetSeedWithCurrentMapPlayerTrackerAndCurrentClearingRewardCount()
	{
		string text = "0";
		if (currentReward != null)
		{
			text = currentReward.RewardsCounter.ToString();
		}
		string s = GetIndexesConcatenated() + text;
		return ReferenceSingleton<AssetsReference>.Instance.PlayerRunStats.GetSeed() + int.Parse(s);
	}

	private string GetIndexesConcatenated()
	{
		return string.Concat(string.Concat("" + CurrentAreaIndex * 100, ((CurrentAreaLevelIndex != -1) ? CurrentAreaLevelIndex : 0).ToString()), ((CurrentNodeIndex != -1) ? CurrentNodeIndex : 0).ToString());
	}

	public int GetSeedWithCurrentMapPlayerTracker()
	{
		return ReferenceSingleton<AssetsReference>.Instance.PlayerRunStats.GetSeed() + int.Parse(GetIndexesConcatenated());
	}

	public void SetTutorialSetup()
	{
		currentBattleSceneSetup = tutorialSetup;
	}

	public void SetEventDebug(CustomEventSetup customEventSetup)
	{
		SetOverrideSetBattleScene(value: true);
		currentReward = normalBattleReward;
		currentBattleSceneSetup = eventSetup;
		currentCustomEventSetup = customEventSetup;
	}

	public void AddOnLastShopNodeExit(Action action)
	{
		OnLastNodeExit = (Action)Delegate.Combine(OnLastNodeExit, action);
	}
}
